def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    lastM, lastO = history[-1]

    opD = 0
    myD = 0
    for h in history:
        if h[1] == 'D':
            opD += 1
        if h[0] == 'D':
            myD += 1

    w = 8 if n >= 8 else n
    recentD = 0
    for i in range(n - w, n):
        if history[i][1] == 'D':
            recentD += 1
    recentC = w - recentD

    tol = 0
    pun = 0
    if n > 1:
        for i in range(n - 1):
            if history[i][0] == 'D':
                if history[i + 1][1] == 'C':
                    tol += 1
                else:
                    pun += 1

    if (recentD >= 6 and myD <= opD + 3) or (opD >= 10 and opD * 3 > n * 2 and myD <= opD + 1):
        return 'D'

    if n >= 2 and lastM == 'D' and lastO == 'D' and history[-2][0] == 'D' and history[-2][1] == 'D':
        return 'C'

    if lastO == 'D':
        return 'D'

    if lastM == 'D':
        if tol >= pun and (opD * 2 <= n or recentC >= 6):
            return 'D'
        return 'C'

    if n < 6:
        if opD == n:
            return 'D'
        return 'C'

    if myD > opD + 3 and recentC >= 5:
        return 'C'

    return 'C'
